import json as _j
good = ['{"a": [1, 2.5, -3e2, true, false, null], "b": {"c": "x\\ny"}}', '[]', '{}', '  42 ', '-0.5E-3',
        '"\\u00e9\\ud83d\\ude00"', '[[[]]]', '{"k":"\\"q\\" \\\\ \\/ \\t"}', '0', '[1e5, 1E+2, 10]']
for g in good:
    assert json_parse(g) == _j.loads(g), g
    assert type(json_parse(g)) == type(_j.loads(g)), g
assert type(json_parse('10')) is int and type(json_parse('1.0')) is float
for bad in ['', '[1,]', '{"a":1,}', '01', "'x'", '"abc', '[1 2]', '{"a" 1}', 'tru', '1 2', '{1:2}', '-', '1.', '.5', '[', '"\\x"']:
    try:
        json_parse(bad); raise SystemExit('accepted invalid: ' + repr(bad))
    except ValueError:
        pass

m = MedianFinder()
try:
    m.median(); raise SystemExit('no error on empty')
except ValueError:
    pass
import random as _r, statistics as _s, time as _t
_r.seed(7); xs=[]
for _ in range(2000):
    v=_r.randint(-1000,1000); xs.append(v); m.add(v)
    assert abs(m.median() - _s.median(xs)) < 1e-9
m2=MedianFinder(); t0=_t.time()
for i in range(200000): m2.add(i)
assert m2.median() == 99999.5 and _t.time()-t0 < 3, 'too slow'
